        function isFirebaseAuthApiBlockedError(error) {
            const code = error && error.code ? String(error.code) : '';
            const message = error && error.message ? String(error.message) : String(error || '');
            const text = (code + ' ' + message).toLowerCase();
            return text.includes('api_key_service_blocked') ||
                ((text.includes('securetoken.googleapis.com') || text.includes('identitytoolkit.googleapis.com')) &&
                    (text.includes('blocked') || text.includes('forbidden'))) ||
                (text.includes('requests-to-this-api') && text.includes('blocked') &&
                    (text.includes('securetoken') || text.includes('identitytoolkit')));
        }

        function firebaseAuthBlockedUserMessage() {
            return 'Live sync authentication is blocked by the Firebase API-key settings. Attendance punches remain safely stored on this device. An admin must allow Identity Toolkit API and Token Service API (securetoken.googleapis.com), then tap Retry Sync.';
        }

        function getUserFacingSyncError(error) {
            return (firebaseAuthApiBlocked || isFirebaseAuthApiBlockedError(error)) ?
                firebaseAuthBlockedUserMessage() : getErrorMessage(error);
        }

        function markFirebaseAuthApiBlocked(error, source) {
            const wasBlocked = firebaseAuthApiBlocked;
            firebaseAuthApiBlocked = true;
            firebaseAuthApiBlockedAt = firebaseAuthApiBlockedAt || Date.now();
            firebaseAuthApiBlockedRetryAt = Date.now() + FIREBASE_AUTH_BLOCKED_RETRY_MS;
            lastConnectionError = error || lastConnectionError || new Error('Firebase Authentication API access is blocked.');
            reconnectFailureCount = Math.max(reconnectFailureCount, 1);
            nextReconnectAttemptAt = Math.max(nextReconnectAttemptAt || 0, firebaseAuthApiBlockedRetryAt);
            if (!wasBlocked) {
                try {
                    appendSyncAudit('auth_api_blocked', 'Firebase Authentication token refresh is blocked by the API-key restrictions; local backup remains active.', {
                        source: source || 'firebase-auth',
                        error: getErrorMessage(lastConnectionError)
                    });
                } catch (e) {}
            }
            setLiveConnectionState(false, source || 'auth-api-blocked');
            setReconnectUi(false, firebaseAuthBlockedUserMessage());
            updateHeaderConnectionStatus();
            try { renderSyncDiagnostics(); } catch (e) {}
        }

        function clearFirebaseAuthApiBlocked() {
            if (!firebaseAuthApiBlocked) return;
            firebaseAuthApiBlocked = false;
            firebaseAuthApiBlockedAt = 0;
            firebaseAuthApiBlockedRetryAt = 0;
            nextReconnectAttemptAt = 0;
            try { appendSyncAudit('auth_api_restored', 'Firebase Authentication API access is working again.', {}); } catch (e) {}
        }

        const SOCKET_DISCONNECT_GRACE_MS = 15000;
        const LIVE_HEARTBEAT_INTERVAL_MS = 45000;
        const LIVE_HEARTBEAT_STALE_MS = 90000;
        const PENDING_SYNC_RETRY_BASE_MS = 5000;
        const PENDING_SYNC_RETRY_MAX_MS = 30000;

        const FIREBASE_RECONNECT_SDKS = [
            ['app', 'https://www.gstatic.com/firebasejs/10.13.2/firebase-app-compat.js'],
            ['database', 'https://www.gstatic.com/firebasejs/10.13.2/firebase-database-compat.js'],
            ['auth', 'https://www.gstatic.com/firebasejs/10.13.2/firebase-auth-compat.js']
        ];

        function withTimeout(promise, timeoutMs, message) {
            let timer = null;
            return Promise.race([
                Promise.resolve(promise),
                new Promise((_, reject) => {
                    timer = setTimeout(() => reject(new Error(message || 'The operation timed out.')), timeoutMs);
                })
            ]).finally(() => {
                if (timer) clearTimeout(timer);
            });
        }

        function loadReconnectSdk(src, key) {
            return new Promise((resolve, reject) => {
                const script = document.createElement('script');
                let settled = false;
                const finish = (error) => {
                    if (settled) return;
                    settled = true;
                    clearTimeout(timeout);
                    if (error) {
                        script.remove();
                        reject(error);
                    } else {
                        resolve();
                    }
                };
                const timeout = setTimeout(() => {
                    finish(new Error('Timed out loading Firebase ' + key + ' SDK.'));
                }, 10000);
                script.async = true;
                script.dataset.reconnectSdk = key;
                script.src = src + (src.includes('?') ? '&' : '?') + 'reconnect=' + Date.now();
                script.onload = () => finish(null);
                script.onerror = () => finish(new Error('Could not load Firebase ' + key + ' SDK.'));
                document.head.appendChild(script);
            });
        }

        async function ensureFirebaseSdk() {
            if (!window.firebase) {
                await loadReconnectSdk(FIREBASE_RECONNECT_SDKS[0][1], FIREBASE_RECONNECT_SDKS[0][0]);
            }
            if (!window.firebase || typeof window.firebase.initializeApp !== 'function') {
                throw new Error('Firebase core SDK is unavailable.');
            }
            if (typeof window.firebase.database !== 'function') {
                await loadReconnectSdk(FIREBASE_RECONNECT_SDKS[1][1], FIREBASE_RECONNECT_SDKS[1][0]);
            }
            if (typeof window.firebase.auth !== 'function') {
                await loadReconnectSdk(FIREBASE_RECONNECT_SDKS[2][1], FIREBASE_RECONNECT_SDKS[2][0]);
            }
            if (typeof window.firebase.database !== 'function' || typeof window.firebase.auth !== 'function') {
                throw new Error('Firebase database/auth SDK is unavailable.');
            }
        }

        async function waitForInitialFirebaseAuthState(auth, timeoutMs = 4000) {
            if (!auth || typeof auth.onAuthStateChanged !== 'function') return auth && auth.currentUser ? auth.currentUser : null;
            return await new Promise(resolve => {
                let settled = false;
                let unsubscribe = null;
                const finish = (user) => {
                    if (settled) return;
                    settled = true;
                    clearTimeout(timer);
                    try { if (unsubscribe) unsubscribe(); } catch (e) {}
                    resolve(user || null);
                };
                const timer = setTimeout(() => finish(auth.currentUser || null), Math.max(500, Number(timeoutMs) || 4000));
                try {
                    unsubscribe = auth.onAuthStateChanged(user => finish(user), () => finish(auth.currentUser || null));
                } catch (e) {
                    finish(auth.currentUser || null);
                }
            });
        }

        async function ensureFirebaseReady(options = {}) {
            const silent = !!options.silent;
            try {
                if (fbDb && window.firebase && window.firebase.auth && window.firebase.auth().currentUser) return fbDb;
            } catch (e) { /* retry below */ }

            if (!firebaseInitPromise) {
                firebaseInitPromise = (async () => {
                    await ensureFirebaseSdk();
                    if (!firebase.apps || !firebase.apps.length) firebase.initializeApp(firebaseConfig);
                    const auth = firebase.auth();
                    const restoredUser = auth.currentUser || await waitForInitialFirebaseAuthState(auth);
                    if (!restoredUser && !auth.currentUser) {
                        await withTimeout(
                            auth.signInAnonymously(),
                            25000,
                            'Timed out signing in to the live server.'
                        );
                    }
                    fbDb = firebase.database();
                    lastConnectionError = null;
                    watchFirebaseTimeOffset();
                    initSync();
                    updateHeaderConnectionStatus();
                    return fbDb;
                })();
            }

            const pendingInit = firebaseInitPromise;
            try {
                return await pendingInit;
            } catch (error) {
                lastConnectionError = error;
                if (isFirebaseAuthApiBlockedError(error)) {
                    markFirebaseAuthApiBlocked(error, 'auth-init-blocked');
                }
                if (!silent) throw error;
                return null;
            } finally {
                if (firebaseInitPromise === pendingInit) firebaseInitPromise = null;
            }
        }

        fbReady = ensureFirebaseReady({ silent: true });

        let serverTimeOffsetMs = 0;      // trueServerMs - Date.now(), kept fresh below
        let timeSyncEstablished = false; // true once at least one trusted source has reported in
        let lastSyncSource = null;       // 'firebase' | 'timeapi.io' | 'worldtimeapi.org', for the admin panel
        let lastSyncAtMs = null;         // Date.now() (device clock) at the moment of the last successful sync
        const timeSyncStartedAtPerf = (typeof performance !== 'undefined' && performance.now) ? performance.now() : 0;

        function getTrueNowMs() {
            return Date.now() + serverTimeOffsetMs;
        }

        function applyServerTimeOffset(offsetMs, source) {
            if (!Number.isFinite(offsetMs)) {
                lastConnectionError = new Error('Received an invalid time offset from ' + (source || 'the server') + '.');
                return false;
            }
            const wasEstablished = timeSyncEstablished;
            serverTimeOffsetMs = offsetMs;
            timeSyncEstablished = true;
            lastSyncSource = source;
            lastSyncAtMs = Date.now();
            timeSyncRetryCount = 0;
            if (timeSyncRetryTimer) {
                clearTimeout(timeSyncRetryTimer);
                timeSyncRetryTimer = null;
            }
            updateHeaderConnectionStatus();
            if (!wasEstablished) {
                const driftMs = Math.abs(offsetMs);
                if (driftMs > 2 * 60 * 1000) {
                    logAudit('clock_drift_detected', {
                        source,
                        driftMinutes: Math.round(driftMs / 60000),
                        deviceClockAheadOfServer: offsetMs < 0
                    });
                }
            }
            if (!wasEstablished) {
                requestAnimationFrame(() => {
                    const root = document.getElementById('appRoot');
                    if (root && root.style.visibility !== 'hidden') refreshPunchCard();
                    if (typeof isOverlayOpen === 'function' && typeof renderTeamLeaderAttendance === 'function' && isOverlayOpen($('tlAttendanceOverlay'))) {
                        renderTeamLeaderAttendance();
                    }
                });
            }
            return true;
        }

        function recordServerStampedPunch(entry) {
            if (!fbDb) return;
            try {
                fbDb.ref('serverTimeAudit').push({
                    action: entry.action,
                    name: entry.name || null,
                    field: entry.field || null,
                    clientTs: entry.ts,
                    serverTs: firebase.database.ServerValue.TIMESTAMP
                }).catch(() => {});
            } catch (e) { /* best-effort only */ }
        }

        function watchFirebaseTimeOffset() {
            if (!fbDb || firebaseTimeOffsetListenerAttached) return;
            try {
                fbDb.ref('.info/serverTimeOffset').on('value', (snap) => {
                    const offset = snap.val();
                    if (Number.isFinite(offset)) applyServerTimeOffset(offset, 'firebase');
                });
                firebaseTimeOffsetListenerAttached = true;
            } catch (error) {
                lastConnectionError = error;
            }
        }

        async function fetchExternalTimeOffset() {
            if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
            const providers = [
                {
                    name: 'timeapi.io',
                    run: async () => {
                        const res = await withTimeout(
                            fetch('https://timeapi.io/api/Time/current/zone?timeZone=UTC', { cache: 'no-store' }),
                            7000,
                            'timeapi.io timed out'
                        );
                        if (!res.ok) throw new Error('timeapi.io bad response');
                        const data = await res.json();
                        return Date.UTC(data.year, data.month - 1, data.day, data.hour, data.minute, data.seconds);
                    }
                },
                {
                    name: 'worldtimeapi.org',
                    run: async () => {
                        const res = await withTimeout(
                            fetch('https://worldtimeapi.org/api/timezone/Asia/Manila', { cache: 'no-store' }),
                            7000,
                            'worldtimeapi.org timed out'
                        );
                        if (!res.ok) throw new Error('worldtimeapi.org bad response');
                        const data = await res.json();
                        return new Date(data.utc_datetime).getTime();
                    }
                }
            ];
            for (const provider of providers) {
                try {
                    const before = Date.now();
                    const serverMs = await provider.run();
                    const roundTripMs = Date.now() - before;
                    if (!Number.isFinite(serverMs)) throw new Error(provider.name + ' returned an invalid time.');
                    if (!applyServerTimeOffset((serverMs + roundTripMs / 2) - Date.now(), provider.name)) {
                        throw new Error(provider.name + ' returned an invalid time offset.');
                    }
                    return true;
                } catch (e) { /* try the next provider */ }
            }
            return false;
        }

        function scheduleTimeSyncRetry(delayMs) {
            if (timeSyncEstablished) return;
            if (timeSyncRetryTimer) clearTimeout(timeSyncRetryTimer);
            timeSyncRetryTimer = setTimeout(async () => {
                timeSyncRetryTimer = null;
                if (timeSyncEstablished) return;
                if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                    scheduleTimeSyncRetry(15000);
                    return;
                }
                const synced = await fetchExternalTimeOffset();
                if (synced || timeSyncEstablished) return;
                timeSyncRetryCount += 1;
                const nextDelay = Math.min(60000, 5000 * Math.pow(2, Math.min(timeSyncRetryCount, 4)));
                scheduleTimeSyncRetry(nextDelay);
            }, Math.max(1000, delayMs));
        }

        function initServerTimeSync() {
            void fetchExternalTimeOffset().then((synced) => {
                if (!synced && !timeSyncEstablished) {
                    timeSyncRetryCount = 1;
                    scheduleTimeSyncRetry(10000);
                }
            });
        }
        initServerTimeSync();

        async function pingLiveServer() {
            const db = await ensureFirebaseReady({ silent: false });
            if (!db) throw new Error('Live database is unavailable.');
            const auth = firebase.auth();
            const user = auth && auth.currentUser;
            if (!user) throw new Error('Live server authentication is unavailable.');
            let token;
            try {
                token = await withTimeout(
                    user.getIdToken(),
                    10000,
                    'Timed out authenticating the live server ping.'
                );
            } catch (error) {
                if (isFirebaseAuthApiBlockedError(error)) {
                    markFirebaseAuthApiBlocked(error, 'auth-token-blocked');
                }
                throw error;
            }
            const pingKey = fbEncodeKey('employees_v');
            const endpoint = firebaseConfig.databaseURL.replace(/\/$/, '') +
                '/kv/' + encodeURIComponent(pingKey) + '.json?auth=' + encodeURIComponent(token);
            const controller = typeof AbortController === 'function' ? new AbortController() : null;
            const timeout = setTimeout(() => { if (controller) controller.abort(); }, 12000);
            try {
                const response = await fetch(endpoint, {
                    method: 'GET',
                    cache: 'no-store',
                    headers: { 'Accept': 'application/json' },
                    signal: controller ? controller.signal : undefined
                });
                if (!response.ok) throw new Error('Live server ping failed with HTTP ' + response.status + '.');
                await response.text();
                clearFirebaseAuthApiBlocked();
                lastLiveServerPingAt = Date.now();
                lastConnectionError = null;
                reconnectFailureCount = 0;
                nextReconnectAttemptAt = 0;
                setLiveConnectionState(true, 'ping');
                try {
                    const offsetSnap = await withTimeout(
                        db.ref('.info/serverTimeOffset').once('value'),
                        5000,
                        'Timed out refreshing the Firebase time offset.'
                    );
                    const offset = offsetSnap.val();
                    if (Number.isFinite(offset)) applyServerTimeOffset(offset, 'firebase');
                } catch (e) { /* the successful REST ping already proved reachability */ }
                return true;
            } finally {
                clearTimeout(timeout);
            }
        }

        async function reconnectToLiveServer(options = {}) {
            const userInitiated = !!options.userInitiated;
            if (reconnectPromise) return reconnectPromise;
            if (firebaseAuthApiBlocked && !userInitiated && Date.now() < firebaseAuthApiBlockedRetryAt) {
                setReconnectUi(false, firebaseAuthBlockedUserMessage());
                setConnBanner(false, { immediate: true });
                return false;
            }
            if (userInitiated && firebaseAuthApiBlocked) {
                firebaseAuthApiBlockedRetryAt = 0;
                nextReconnectAttemptAt = 0;
            }
            reconnectPromise = (async () => {
                if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                    throw new Error('This device is still offline.');
                }
                setReconnectUi(true, 'Checking the live server...');
                const db = await ensureFirebaseReady({ silent: false });
                if (!db) throw new Error('Could not initialize the live database.');
                try {
                    if (typeof db.goOnline === 'function') db.goOnline();
                } catch (e) { /* ping below is authoritative */ }
                initSync();
                await pingLiveServer();
                reconnectFailureCount = 0;
                nextReconnectAttemptAt = 0;
                await flushPendingRecords();
                const pendingAfterReconnect = getPendingSyncSummary();
                if (userInitiated) {
                    showToast(pendingAfterReconnect.total ?
                        'Live server reached. Saved changes are still retrying.' :
                        'Connection restored. Local backup is synced to the live server.');
                }
                return true;
            })();

            try {
                return await reconnectPromise;
            } catch (error) {
                lastConnectionError = error;
                const pendingNow = getPendingSyncSummary();
                if (firebaseAuthApiBlocked || isFirebaseAuthApiBlockedError(error)) {
                    markFirebaseAuthApiBlocked(error, 'reconnect-auth-blocked');
                    clearPendingSyncRetryTimer();
                    if (pendingNow.total) schedulePendingSyncRetry(FIREBASE_AUTH_BLOCKED_RETRY_MS);
                    if (userInitiated) showToast(getUserFacingSyncError(error), 7000);
                    return false;
                }
                reconnectFailureCount += 1;
                const retryDelay = pendingNow.punchWrites > 0 ?
                    Math.min(PENDING_SYNC_RETRY_MAX_MS, PENDING_SYNC_RETRY_BASE_MS * Math.pow(2, Math.min(reconnectFailureCount - 1, 3))) :
                    Math.min(120000, 15000 * Math.pow(2, Math.min(reconnectFailureCount - 1, 3)));
                nextReconnectAttemptAt = Date.now() + retryDelay;
                setLiveConnectionState(false, 'reconnect-failed');
                setReconnectUi(false, 'Live server is still unavailable. Your changes remain saved on this device.');
                setConnBanner(false, { immediate: pendingNow.punchWrites > 0 });
                if (pendingNow.total) {
                    clearPendingSyncRetryTimer();
                    schedulePendingSyncRetry(retryDelay);
                }
                if (userInitiated) showToast(getUserFacingSyncError(error), 6000);
                return false;
            } finally {
                reconnectPromise = null;
                const banner = $('connBanner');
                if (banner) banner.classList.remove('is-checking');
                setReconnectBusy(false);
                setConnBanner(fbConnected === true, { immediate: getPendingSyncSummary().punchWrites > 0 });
                updateHeaderConnectionStatus();
            }
        }

        function fbEncodeKey(str) {
            try {
                return btoa(unescape(encodeURIComponent(str))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
            } catch (e) { return str; }
        }
        function fbDecodeKey(str) {
            try {
                let b64 = str.replace(/-/g, '+').replace(/_/g, '/');
                while (b64.length % 4) b64 += '=';
                return decodeURIComponent(escape(atob(b64)));
            } catch (e) { return str; }
        }

        // ======================================================================
        // CONSTANTS & DATA
        // ======================================================================
        const TEAM_CWH = "CWH";
        const TEAM_ALBERTSONS = "ALBERTSONS";
        const CWH_POD_LIST = [
            "ONBOARDING", "TESCO", "KROGER",
            "POD 0", "POD 1", "POD 2", "POD 3", "POD 4", "POD 5", "POD 6",
            "POD 7", "POD 8", "POD 9", "POD 10", "POD 11", "POD 12"
        ];
        const ALBERTSONS_POD_LIST = [
            "Albertsons · POD 0", "Albertsons · POD 1", "Albertsons · POD 2", "Albertsons · POD 3", "Albertsons · POD 4"
        ];
        const ALBERTSONS_ROSTER_SEED_VERSION = 1;
        // v76.12 privacy hardening: the deployable client no longer ships the Albertsons employee seed.
        // The live database-managed employees payload is authoritative.
        const ALBERTSONS_AGENT_ROSTER = Object.freeze([])
        const TEAM_GROUPS = [
            { id: TEAM_CWH, label: "CWH", fullName: "Chemist Warehouse", pods: CWH_POD_LIST },
            { id: TEAM_ALBERTSONS, label: "Albertsons", fullName: "Albertsons", pods: ALBERTSONS_POD_LIST }
        ];
        const POD_LIST = [...CWH_POD_LIST, ...ALBERTSONS_POD_LIST];
        const ALL_PODS_LABEL = "All Pods";

        // ======================================================================
        // UNIFIED EDITION ACCESS POLICY
        // ======================================================================
        // POD-level Premium access retains the existing shared policy. Bebless has
        // a separate, server-protected account entitlement keyed by an immutable
        // employee ID. The secure entitlement deliberately lives OUTSIDE /kv so a
        // broad legacy /kv write grant cannot override its Firebase Rules.
        const PREMIUM_ACCESS_POLICY_KEY = 'premium_access_policy_v1';
        const PREMIUM_ACCESS_POLICY_VERSION = 1;
        const PREMIUM_ACCESS_MANAGER_NAME = 'Jhan Roi Celo';
        const PREMIUM_ACCESS_MANAGER_POD = 'POD 2';
        const PREMIUM_DEFAULT_POD = 'POD 2';
        const PREMIUM_BEBLESS_LEGACY_ACCESS_KEY = 'premium_account_access_bebless_v1';
        const PREMIUM_BEBLESS_ACCESS_VERSION = 2;
        const PREMIUM_BEBLESS_EMPLOYEE_ID = 'tt_emp_bebless_velasco_p0_001';
        const PREMIUM_BEBLESS_CANONICAL_NAME = 'Bebless Velasco';
        const PREMIUM_BEBLESS_LEGACY_NAME = 'Velasco';
        const PREMIUM_BEBLESS_ORIGINAL_POD = 'POD 0';
        const PREMIUM_BEBLESS_SECURE_ROOT = 'securePremiumEntitlements';
        const PREMIUM_BEBLESS_SECURE_PATH = PREMIUM_BEBLESS_SECURE_ROOT + '/' + PREMIUM_BEBLESS_EMPLOYEE_ID;
        const PREMIUM_MANAGER_FIREBASE_APP_NAME = 'trinotime-premium-manager-v1';
        const PREMIUM_MANAGER_SERVER_ROLE = 'premium_manager';
        const PREMIUM_MANAGER_PERMISSION = 'beblessPremium';
        const PREMIUM_MANAGER_PRIVILEGE_LABEL = 'Developer · Premium Manager';
