            return {name,pod,role,dateStr,available,canAutoAssign:available&&!conflict,code,sourceKind,reason,leaveRequest,fullDayLeave,scheduledDayOff,dayOffSwap:swap||null,tlDateOverride:tlDateOverride||null,workAuthorization:tlWorkAuthorization||null,conflict,baseSourceKind};
