        const PENDING_DELETE_PREFIX = 'pending-delete:';
        const PUNCH_EVENT_PREFIX = 'punch-event:';
        const SYNC_AUDIT_KEY = 'sync_audit_v1';
        const SYNC_AUDIT_MAX = 20;
        const PENDING_WARNING_MS = 30000;
        const PENDING_CRITICAL_MS = 120000;
        const FIREBASE_READ_TIMEOUT_MS = 12000;
        const FIREBASE_WRITE_TIMEOUT_MS = 15000;
