            const moveAgentsTab = $('moveAgentsTabBtn');
            if (moveAgentsTab) moveAgentsTab.style.display = (isAdmin || isTeamLeader) ? 'inline-block' : 'none';
            const otTab = $('otTabBtn');
            if (otTab) otTab.style.display = (isAdmin || isTeamLeader) ? 'inline-block' : 'none';
            const networkTab = $('networkTabBtn');
            if (networkTab) networkTab.style.display = (isAdmin || isTeamLeader) ? 'inline-block' : 'none';
