        async function performClearAgentAttendanceHistory() {
            const recordKeys = Object.keys(allRecords).filter(k => dailyNoteRecordHasOtherData(allRecords[k]));
            const otKeys = Object.keys(allOT);
            if (recordKeys.length === 0 && otKeys.length === 0) {
                showToast('There is no punch or overtime history to clear. Daily notes are unchanged.');
                return;
            }
            const otLabel = otKeys.length === 1 ? '1 OT entry' : `${otKeys.length} OT entries`;
            const recLabel = recordKeys.length === 1 ? '1 attendance record' : `${recordKeys.length} attendance records`;
            const notesKept = recordKeys.reduce((count, key) => count + (normalizeDailyNoteText(allRecords[key] && allRecords[key].note) ? 1 : 0), 0);
            const recordsSnapshot = JSON.parse(JSON.stringify(allRecords));
            const otSnapshot = JSON.parse(JSON.stringify(allOT));
            const notesOnlyRecords = {};
            Object.entries(allRecords).forEach(([key, rec]) => {
                const idx = key.indexOf('|');
                const date = idx >= 0 ? key.slice(0, idx) : '';
                const name = idx >= 0 ? key.slice(idx + 1) : '';
                const noteOnly = dailyNoteOnlyRecord(rec, name, date);
                if (noteOnly) notesOnlyRecords[key] = noteOnly;
            });

            allRecords = notesOnlyRecords;
            allOT = {};
            refreshPunchCard();
            refreshDailyNoteViews();
            if (typeof renderHistoryCalendar === 'function') { try { renderHistoryCalendar(); } catch (e) {} }

            let undone = false;
            const commitClear = setTimeout(async () => {
                if (undone) return;
                try {
                    for (const k of recordKeys) {
                        const idx = k.indexOf('|');
                        const date = k.slice(0, idx);
                        const name = k.slice(idx + 1);
                        if (notesOnlyRecords[k]) await appStorage.set(recKey(date, name), JSON.stringify(notesOnlyRecords[k]));
                        else await appStorage.delete(recKey(date, name));
                    }
                    for (const k of otKeys) {
                        const idx = k.indexOf('|');
                        const date = k.slice(0, idx);
                        const name = k.slice(idx + 1);
                        await appStorage.delete(otRecKey(date, name));
                    }
                } catch (e) { reportAppError('Clear attendance history', e, { notify: true }); }
                try { await logAudit('clear_agent_attendance_history', { name: 'Admin', recordCount: recordKeys.length, otCount: otKeys.length, notesKept }); } catch (e) {}
            }, 6000);

            const keptText = notesKept ? ` Kept ${notesKept} dated ${notesKept === 1 ? 'note' : 'notes'}.` : '';
            showToast(`Cleared ${recLabel} and ${otLabel}.${keptText}`, 6000, 'Undo', () => {
                undone = true;
                clearTimeout(commitClear);
                allRecords = recordsSnapshot;
                allOT = otSnapshot;
                refreshPunchCard();
                refreshDailyNoteViews();
                if (typeof renderHistoryCalendar === 'function') { try { renderHistoryCalendar(); } catch (e) {} }
                showToast('Clear undone.');
            });
        }

        const settingsClearHistoryBtn = $('settingsClearHistoryBtn');
        if (settingsClearHistoryBtn) settingsClearHistoryBtn.addEventListener('click', () => {
            void runAsyncAction(async () => {
                setDataManagementError('');
                if (!TrinoPermissions.can('data.manage')) { setDataManagementError('An authenticated Admin session is required.'); return; }
                const pass = String($('dataManagementAdminPass').value || '');
                const phrase = String($('dataManagementConfirmPhrase').value || '').trim();
                try {
                    if (!pass) throw new Error('Missing password');
                    await reauthenticateCurrentFirebaseAdmin(pass);
                } catch (error) {
                    setDataManagementError('The Firebase Admin password is incorrect, or this Admin role is no longer active.');
                    return;
                }
                if (phrase !== 'CLEAR AGENT HISTORY') {
                    setDataManagementError('Type CLEAR AGENT HISTORY exactly to continue.');
                    return;
                }
                $('dataManagementAdminPass').value = '';
                $('dataManagementConfirmPhrase').value = '';
                await performClearAgentAttendanceHistory();
            }, 'Clear agent attendance and overtime history');
        });

        async function performClearTeamLeaderAttendanceHistory() {
            const recordKeys = Object.keys(allTeamLeaderRecords);
            if (recordKeys.length === 0) {
                showToast('There is no Team Leader attendance history to clear.');
                return;
            }
            const snapshot = JSON.parse(JSON.stringify(allTeamLeaderRecords));
            const label = recordKeys.length === 1 ? '1 Team Leader attendance record' : `${recordKeys.length} Team Leader attendance records`;

            allTeamLeaderRecords = {};
            if (typeof renderTeamLeaderAttendance === 'function' && isOverlayOpen($('tlAttendanceOverlay'))) {
                try { renderTeamLeaderAttendance(); } catch (e) {}
            }

            let undone = false;
            const commitClear = setTimeout(async () => {
                if (undone) return;
                try {
                    for (const mapKey of recordKeys) {
                        const idx = mapKey.indexOf('|');
                        const date = idx >= 0 ? mapKey.slice(0, idx) : '';
                        const name = idx >= 0 ? mapKey.slice(idx + 1) : '';
                        if (!date || !name) continue;
                        const storageKey = tlAttendanceRecordKey(date, name);
                        safeLocalRemove(PENDING_PREFIX + storageKey);
                        await appStorage.delete(storageKey);
                    }
                } catch (e) {
                    reportAppError('Clear Team Leader attendance history', e, { notify: true });
                }
                try {
                    await logAudit('clear_tl_attendance_history', {
                        name: 'Admin',
                        recordCount: recordKeys.length,
                        teams: [TEAM_CWH, TEAM_ALBERTSONS]
                    });
                } catch (e) {}
            }, 6000);

            showToast(`Cleared ${label}. Agent attendance and OT were not changed.`, 6000, 'Undo', () => {
                undone = true;
                clearTimeout(commitClear);
                allTeamLeaderRecords = snapshot;
                if (typeof renderTeamLeaderAttendance === 'function' && isOverlayOpen($('tlAttendanceOverlay'))) {
                    try { renderTeamLeaderAttendance(); } catch (e) {}
                }
                showToast('Team Leader attendance clear undone.');
            });
        }

