            const assignTeamId = lockedPod && !isAdmin ? teamIdForPod(lockedPod) : activeTeam;
            populateAssignTeamAndPodOptions(assignTeamId, lockedPod && !isAdmin ? lockedPod : (activePod === ALL_PODS_LABEL ? '' : activePod));
            $('assignName').value = '';
