        if ($('assignTeam')) $('assignTeam').addEventListener('change', e => populateAssignTeamAndPodOptions(e.target.value, ''));
        $('assignSaveBtn').addEventListener('click', () => {
            void runAsyncAction(async () => {
            const name = $('assignName').value.trim();
            const pod = (lockedPod && !isAdmin) ? lockedPod : $('assignPod').value;
            if (!TrinoPermissions.can('agent.roster.add', { name, pod })) {
                showToast('You can add or assign Agents only within your authorized POD scope.');
                $('assignOverlay').classList.remove('open');
                return;
            }
            const destinationTeam = teamIdForPod(pod);
            if (!name) { showToast('Enter a name first.'); return; }
            if (name.length > 60) { showToast('Agent names are limited to 60 characters.'); return; }
            const existing = employees.find(e => e.name.toLowerCase() === name.toLowerCase());
            if (existing && lockedPod && !isAdmin && existing.pod !== lockedPod) {
                showToast(`${agentDisplayName(existing.name)} belongs to ${existing.pod} — ask an Admin or that pod's Team Leader to move them.`);
                return;
            }
            if (existing) {
                const result = await transferAgentsToPod([existing.name], pod, { confirmMove:false, origin:'Add / assign Agent' });
                if (result && result.moved && result.moved.length) showToast(`Moved ${agentDisplayName(existing.name)} to ${podContextLabel(pod)}.`);
                else showToast(`${agentDisplayName(existing.name)} is already assigned to ${podContextLabel(pod)}.`);
            } else {
                employees.push({ name, pod });
                await saveEmployees();
                showToast(`Added ${name} to ${teamGroupById(destinationTeam).fullName} · ${podDisplayName(pod)}.`);
            }
            $('assignOverlay').classList.remove('open');
            populateEmployeeSelects();
            renderTable();
            if (isOverlayOpen($('rosterOverlay'))) renderRosterTab();
            }, 'Assign Agent');
        });
