        $('shiftSettingsSaveBtn').addEventListener('click', () => {
            void runAsyncAction(async () => {
            if (!TrinoPermissions.can('schedule.shift_settings.manage')) {
                showToast('Only an authenticated Team Leader or Admin can manage shift settings.');
                $('shiftSettingsOverlay').classList.remove('open');
                return;
            }
            const ndSettingsEnabled = nightDiffEnabledForCurrentView();
            const previousNdBreakPolicy = shiftSettings.nightDiffSubtractBreaks ? 'subtract-break-overlap' : 'count-full-span';
            const groups = {};
            SHIFT_GROUP_DEFS.forEach(g => {
                const startEl = $('shiftStart_' + g.id);
                const endEl = $('shiftEnd_' + g.id);
                groups[g.id] = {
                    start: (startEl && startEl.value) || DEFAULT_SHIFT_SETTINGS.groups[g.id].start,
                    end: (endEl && endEl.value) || DEFAULT_SHIFT_SETTINGS.groups[g.id].end
                };
            });
            const altStartEl = $('shiftAltStart');
            const altEndEl = $('shiftAltEnd');
            shiftSettings = {
                maxBreakMinutes: BREAK_ALLOWANCE_MINUTES,
                nightDiffSubtractBreaks: ndSettingsEnabled
                    ? Boolean($('shiftNightDiffBreakPolicy') && $('shiftNightDiffBreakPolicy').value === 'subtract')
                    : shiftSettings.nightDiffSubtractBreaks,
                groups,
                alternateShift: {
                    id: 'early',
                    label: 'Early shift',
                    start: (altStartEl && altStartEl.value) || DEFAULT_SHIFT_SETTINGS.alternateShift.start,
                    end: (altEndEl && altEndEl.value) || DEFAULT_SHIFT_SETTINGS.alternateShift.end
                }
            };
            await saveShiftSettings();
            const nextNdBreakPolicy = shiftSettings.nightDiffSubtractBreaks ? 'subtract-break-overlap' : 'count-full-span';
            if (ndSettingsEnabled && previousNdBreakPolicy !== nextNdBreakPolicy) {
                await logAudit('shift_settings_update', {
                    name: 'Night Differential',
                    oldBreakPolicy: previousNdBreakPolicy,
                    newBreakPolicy: nextNdBreakPolicy,
                    editedBy: isAdmin ? 'Admin' : (teamLeaderName || 'Team Leader')
                });
            }
            $('shiftSettingsOverlay').classList.remove('open');
            lastPunchCardRenderKey = null;
            refreshPunchCard();
            renderTable();
            renderTodayStatus();
            if (isOverlayOpen($('historyOverlay'))) renderHistoryCalendar();
            if (isOverlayOpen($('totalsOverlay'))) renderTotalsTab();
            showToast(ndSettingsEnabled ? 'Shift times and Albertsons Night Diff defaults updated. Break allowance remains fixed at 30 minutes.' : 'Shift times updated. Break allowance remains fixed at 30 minutes.');
            }, 'Save shift settings');
        });
