        $('leavePendingList').addEventListener('click', async (e) => {
            const btn = e.target.closest('[data-leave-action][data-leave-id]');
            if (!btn) return;
            const id = btn.dataset.leaveId;
            const action = btn.dataset.leaveAction;
            if (action === 'approve') {
                if (!(await showConfirmAsync(
                    'Approve Leave Request?',
                    'Approve this leave request and sync its date range to the schedule?',
                    { confirmLabel:'Approve Request', cancelLabel:'Cancel', kind:'leave-approve' }
                ))) return;
                btn.disabled = true;
                void updateLeaveRequestStatus(id, 'APPROVED').catch(error => showToast(getErrorMessage(error))).finally(() => { btn.disabled = false; });
            } else if (action === 'reject') {
                const note = await showPromptAsync(
                    'Reject Leave Request?',
                    'Reject this leave request? You may record an optional reason for the audit trail.',
                    { label:'Rejection reason', placeholder:'Optional reason', required:false, maxLength:800 },
                    { confirmLabel:'Reject Request', cancelLabel:'Cancel', tone:'danger', kind:'leave-reject' }
                );
                if (note === null) return;
                btn.disabled = true;
                void updateLeaveRequestStatus(id, 'REJECTED', note).catch(error => showToast(getErrorMessage(error))).finally(() => { btn.disabled = false; });
            }
        });

