        let leaveV3PilotRenderTimer = null;
        function leaveV3SchedulePilotRender() {
            if (leaveV3PilotRenderTimer) return;
            leaveV3PilotRenderTimer = setTimeout(() => { leaveV3PilotRenderTimer=null; renderLeaveV3All(); }, 50);
        }
        function leaveV3ApplyPilotKvValue(key, raw) {
            if (window.TRINOTIME_LEAVE_FREE_PILOT !== true || !key || typeof raw !== 'string' || hasPendingWrite(key) || hasPendingDelete(key)) return;
            try {
                if (key === LEAVE_V3_POLICY_KEY) { leavePolicyV3=leaveV3NormalizePolicy(JSON.parse(raw)); leaveV3SchedulePilotRender(); return; }
                if (key.startsWith(LEAVE_V3_LOCAL_LEDGER_PREFIX)) { const entry=leaveV3NormalizeEntry(JSON.parse(raw)); if(entry&&entry.id){allLeaveLedgerV3[entry.id]=entry;leaveV3SchedulePilotRender();} return; }
                if (key.startsWith(LEAVE_V3_PROFILE_PREFIX)) { const profile=JSON.parse(raw); const id=key.slice(LEAVE_V3_PROFILE_PREFIX.length); if(profile&&id){leaveEmploymentProfilesV3[id]=profile;leaveV3SchedulePilotRender();} }
            } catch(e) {}
        }
        const leaveV3LegacyApplyKvSnapshot = applyKvSnapshot;
        applyKvSnapshot = function(val) {
            const result=leaveV3LegacyApplyKvSnapshot(val);
            if(window.TRINOTIME_LEAVE_FREE_PILOT===true&&val){Object.keys(val).forEach(encoded=>{try{leaveV3ApplyPilotKvValue(fbDecodeKey(encoded),val[encoded]);}catch(e){}});}
            return result;
        };
        const leaveV3LegacyApplyKvChildUpsert = applyKvChildUpsert;
        applyKvChildUpsert = function(encodedKey,raw) {
            const result=leaveV3LegacyApplyKvChildUpsert(encodedKey,raw);
            try{leaveV3ApplyPilotKvValue(fbDecodeKey(encodedKey),raw);}catch(e){}
            return result;
        };
        const leaveV3LegacyApplyKvChildRemove = applyKvChildRemove;
        applyKvChildRemove = function(encodedKey) {
            let key=''; try{key=fbDecodeKey(encodedKey);}catch(e){}
            const result=leaveV3LegacyApplyKvChildRemove(encodedKey);
            if(window.TRINOTIME_LEAVE_FREE_PILOT===true&&key&&!hasPendingWrite(key)){
                if(key===LEAVE_V3_POLICY_KEY){leavePolicyV3=leaveV3NormalizePolicy(null);leaveV3SchedulePilotRender();}
                else if(key.startsWith(LEAVE_V3_LOCAL_LEDGER_PREFIX)){delete allLeaveLedgerV3[key.slice(LEAVE_V3_LOCAL_LEDGER_PREFIX.length)];leaveV3SchedulePilotRender();}
                else if(key.startsWith(LEAVE_V3_PROFILE_PREFIX)){delete leaveEmploymentProfilesV3[key.slice(LEAVE_V3_PROFILE_PREFIX.length)];leaveV3SchedulePilotRender();}
            }
            return result;
        };

        function leaveV3MaybeRefreshServerData(force=false) {
            if(!leaveV3ServerCapable || leaveV3Loading) return;
            if(!force && leaveV3LastLoadedAt && Date.now()-leaveV3LastLoadedAt<15000) return;
            void Promise.all([leaveV3LoadSecureRequests(),leaveV3LoadPolicy(true),leaveV3LoadLedger(true)]).then(()=>{refreshLeaveAffectedViews(null);renderLeaveV3All();}).catch(()=>{});
        }


        function leaveV3LockedTransitionMessage(request, nextStatus) {
            if (!request || leaveV3ServerCapable) return '';
            const status = normalizeLeaveStatus(nextStatus);
            if (status === 'APPROVED') {
                const startYear=Number(String(request.startDate||'').slice(0,4)), endYear=Number(String(request.endDate||request.startDate||'').slice(0,4));
                for (let year=startYear; year<=endYear; year++) {
                    if (!(leaveV3RequestUnitsForYear(request,year) > 0)) continue;
                    const effective=leaveV3UsageEffectiveDateForYear(request,year);
                    if (leaveV3PolicyLocked(effective)) return 'This leave would post into an HR period locked through ' + leavePolicyV3.lockedThrough + '. Reopen/correct the period before approving it.';
                }
            }
            if (status === 'CANCELLED') {
                const usages=Object.values(allLeaveLedgerV3).map(leaveV3NormalizeEntry).filter(entry=>entry&&entry.sourceRequestId===String(request.id)&&entry.kind==='LEAVE_USAGE');
                for (const usage of usages) {
                    const reversed=Object.values(allLeaveLedgerV3).some(entry=>entry&&entry.kind==='LEAVE_REVERSAL'&&String(entry.voidsEntryId||'')===String(usage.id||''));
                    if (!reversed && leaveV3PolicyLocked(usage.effectiveDate)) return 'This leave usage is in an HR period locked through ' + leavePolicyV3.lockedThrough + '. Post an approved correction in an open period before cancelling the request.';
                }
            }
            return '';
        }

        updateLeaveRequestStatus = async function(id,nextStatus,decisionNote='') {
            const current=allLeaveRequests[id];
            const lockMessage=leaveV3LockedTransitionMessage(current,nextStatus);
            if(lockMessage) throw new Error(lockMessage);
            const result=await leaveV3LegacyUpdateLeaveStatus(id,nextStatus,decisionNote);
            const request=allLeaveRequests[id]||result;
            try{await leaveV3EnsureRequestLedger(request);}catch(error){reportAppError('Leave ledger request sync',error);if(leaveV2ServerRequired())throw error;}
            renderLeaveV3All();
            return result;
        };

