            function bindLinkedNames(){document.addEventListener('click',event=>{const link=event.target.closest&&event.target.closest('[data-profile-directory-link]');if(!link||!viewerAllowed())return;const name=text(link.dataset.profileDirectoryLink);if(!name)return;event.preventDefault();event.stopPropagation();openModal(name,roleForName(name),text(link.dataset.profileDirectorySource)||'linked-name');});}
