            window.TrinoTimeProfileDirectoryDiagnostics=Object.freeze({version:VERSION,snapshot:()=>{const fab=byId('profileDirectorySearchFab'),drawer=byId('profileDirectorySearchDrawer'),root=byId('profileDirectorySearch'),slot=byId('profileDirectorySearchSlot'),overlay=byId('profileDirectoryOverlay');return {runtime:document.documentElement.dataset.profileDirectoryRuntime||'',viewer:viewerContext(),fabExists:!!fab,fabHidden:fab?!!fab.hidden:null,drawerExists:!!drawer,drawerOpen:!!(drawer&&drawer.classList.contains('open')),launcherExists:!!fab,launcherHidden:fab?!!fab.hidden:null,searchExists:!!root,searchHidden:root?!!root.hidden:null,slotExists:!!slot,slotHidden:slot?!!slot.hidden:null,linkedNameCount:document.querySelectorAll('[data-profile-directory-link]').length,modalExists:!!overlay,modalOpen:!!(overlay&&overlay.classList.contains('open'))};}});
