        // ======================================================================
        // ADMIN REVIEW CENTER + UNIFIED SYSTEM HEALTH · v75
        // ======================================================================
        const ADMIN_REVIEW_RENDER_LIMIT = 30;
        const ADMIN_REVIEW_NETWORK_WINDOW_MS = 24 * MS_PER_HOUR;
        const ADMIN_REVIEW_TEMP_CREDENTIAL_AGE_MS = 24 * MS_PER_HOUR;
        const ADMIN_REVIEW_SHIFT_END_GRACE_MS = 30 * 60 * 1000;
        const ADMIN_REVIEW_BREAK_GRACE_MS = 10 * 60 * 1000;
        let adminOpsLastSignature = '';
        let adminOpsLastRenderAt = 0;

        function adminOpsIsVisible() {
            return Boolean(isAdmin && TrinoPermissions.can('admin.review.view'));
        }

        function adminOpsPodInScope(pod) {
            const value = String(pod || '');
            if (!value) return true;
            if (teamIdForPod(value) !== activeTeam) return false;
            return activePod === ALL_PODS_LABEL || !activePod || value === activePod;
        }

        function adminOpsFormatAge(ms) {
            const value = Number(ms);
            if (!Number.isFinite(value) || value < 0) return 'unknown';
            if (value < 60000) return '<1 min';
            const minutes = Math.floor(value / 60000);
            if (minutes < 60) return `${minutes} min`;
            const hours = Math.floor(minutes / 60);
            if (hours < 24) return `${hours}h ${minutes % 60}m`;
            const days = Math.floor(hours / 24);
            return `${days}d ${hours % 24}h`;
        }

        function adminOpsVersionLabel() {
            const meta = document.querySelector('meta[name="trinotime-version"]');
            return meta ? String(meta.content || 'Unknown build') : 'Unknown build';
        }

        function adminSystemHealthSnapshot(nowMs = getTrueNowMs()) {
            const browserOnline = typeof navigator === 'undefined' ? true : navigator.onLine !== false;
            const pending = getPendingSyncSummary();
            const heartbeatAgeMs = lastLiveServerPingAt ? Math.max(0, Date.now() - lastLiveServerPingAt) : null;
            const heartbeatStale = heartbeatAgeMs === null || heartbeatAgeMs >= LIVE_HEARTBEAT_STALE_MS;
            const socketOkay = socketReportedConnected !== false;
            const firebaseOkay = fbConnected === true && socketOkay && !heartbeatStale && !firebaseAuthApiBlocked;
            let pwaLabel = 'Unsupported';
            let pwaState = 'neutral';
            try {
                if ('serviceWorker' in navigator) {
                    if (navigator.serviceWorker.controller) { pwaLabel = 'Active'; pwaState = 'good'; }
                    else { pwaLabel = 'Available · reload may activate'; pwaState = 'neutral'; }
                }
            } catch (_) {}

            let state = 'healthy';
            let label = 'All systems operational';
            let summary = 'Live sync, verified time, and the local safety queue are operating normally.';
            if (!browserOnline) {
                state = timeSyncEstablished ? 'offline' : 'critical';
                label = timeSyncEstablished ? 'Offline · local backup active' : 'Offline · attendance protection active';
                summary = timeSyncEstablished ? 'This device is offline. Verified time is cached and local changes will retry after reconnection.' : 'This device is offline and trusted time is unavailable. Punch controls should remain disabled.';
            } else if (firebaseAuthApiBlocked) {
                state = 'critical';
                label = 'Firebase authentication blocked';
                summary = 'The browser can reach the internet, but Firebase token refresh is blocked. Local backups remain protected while sync retries.';
            } else if (!timeSyncEstablished || fbConnected === false) {
                state = 'critical';
                label = 'Live verification unavailable';
                summary = 'TrinoTime has not established both a trusted clock and live Firebase connection yet.';
            } else if (pending.severity === 'critical') {
                state = 'critical';
                label = 'Pending data requires attention';
                summary = 'Locally protected changes have been waiting too long for server confirmation. Retry live sync.';
            } else if (!firebaseOkay || pending.total > 0) {
                state = 'degraded';
                label = pending.total > 0 ? 'Online · syncing pending data' : 'Connection degraded';
                summary = pending.total > 0 ? 'The server is reachable, but some locally saved changes are still awaiting confirmation.' : 'TrinoTime is online, but the live Firebase heartbeat or socket is being re-verified.';
            }

            const offsetSeconds = Math.round(Number(serverTimeOffsetMs || 0) / 1000);
            return {
                state, label, summary, browserOnline, pending, heartbeatAgeMs, heartbeatStale,
                firebaseOkay, socketOkay, pwaLabel, pwaState, offsetSeconds,
                metrics: [
                    { id:'internet', label:'Internet', value:browserOnline ? 'Online' : 'Offline', state:browserOnline ? 'good' : 'bad' },
                    { id:'firebase', label:'Firebase', value:firebaseAuthApiBlocked ? 'Auth blocked' : (firebaseOkay ? 'Connected' : (fbConnected === true ? 'Re-verifying' : (fbConnected === false ? 'Disconnected' : 'Checking'))), state:firebaseAuthApiBlocked || fbConnected === false ? 'bad' : (firebaseOkay ? 'good' : 'warn') },
                    { id:'time', label:'Server time', value:timeSyncEstablished ? `Verified · ${offsetSeconds >= 0 ? '+' : ''}${offsetSeconds}s correction` : 'Not verified', state:timeSyncEstablished ? 'good' : 'bad' },
                    { id:'pending', label:'Pending sync', value:pending.total ? `${pending.total} change${pending.total === 1 ? '' : 's'} · ${pending.severity}` : '0 · clear', state:pending.severity === 'critical' ? 'bad' : (pending.total ? 'warn' : 'good') },
                    { id:'heartbeat', label:'Last heartbeat', value:lastLiveServerPingAt ? `${adminOpsFormatAge(heartbeatAgeMs)} ago` : 'No confirmation yet', state:heartbeatStale ? 'warn' : 'good' },
                    { id:'write', label:'Last server write', value:lastServerConfirmedWriteAt ? `${adminOpsFormatAge(Math.max(0, nowMs - lastServerConfirmedWriteAt))} ago` : 'No write this session', state:'neutral' },
                    { id:'pwa', label:'PWA / service worker', value:pwaLabel, state:pwaState },
                    { id:'build', label:'Build', value:adminOpsVersionLabel(), state:'neutral' }
                ]
            };
        }

        function adminReviewIssue(category, severity, title, detail, action = null, extra = {}) {
            return {
                category:String(category || 'Review'), severity:['critical','warning','info'].includes(severity) ? severity : 'warning',
                title:String(title || 'Needs review'), detail:String(detail || ''), action, ...extra
            };
        }

        function adminReviewDeduplicateIssues(items) {
            const rank = { critical:0, warning:1, info:2 }, out = [], byKey = new Map();
            (items || []).forEach(item => {
                if (!item) return;
                const key = String(item.dedupeKey || [item.category,item.action,item.name,item.date,item.pod,item.requestId,item.sessionId,item.title].join('|'));
                const prior = byKey.get(key);
                if (!prior) { const copy={...item}; byKey.set(key,copy); out.push(copy); return; }
                const details = Array.from(new Set([prior.detail,item.detail].filter(Boolean)));
                prior.detail = details.join(' · ');
                if ((rank[item.severity] ?? 9) < (rank[prior.severity] ?? 9)) {
                    prior.severity=item.severity; prior.title=item.title; prior.action=item.action || prior.action;
                }
                prior.relatedCount = Number(prior.relatedCount || 1) + 1;
            });
            return out;
        }

        function adminReviewIncompleteAgentIssues(nowMs) {
            const issues = [];
            Object.entries(allRecords || {}).forEach(([key, rec]) => {
                if (!rec || !rec.timeIn || rec.logOut || isVoidedAttendanceRecord(rec)) return;
                const splitAt = key.indexOf('|');
                if (splitAt < 0) return;
                const date = key.slice(0, splitAt);
                const name = key.slice(splitAt + 1);
                const pod = rec.pod || podOf(name) || '';
                if (!adminOpsPodInScope(pod)) return;
                const startMs = new Date(rec.timeIn).getTime();
                if (!Number.isFinite(startMs)) return;
                const ageMs = Math.max(0, nowMs - startMs);
                let scheduledEndMs = NaN;
                try {
                    const range = getShiftBoundaryRangeMs(date, getShiftWindowForRecord(rec, pod));
                    scheduledEndMs = range && Number.isFinite(range.endMs) ? range.endMs : NaN;
                } catch (_) {}
                const pastScheduledEndMs = Number.isFinite(scheduledEndMs) ? nowMs - scheduledEndMs : NaN;
                const pastGrace = Number.isFinite(pastScheduledEndMs) && pastScheduledEndMs >= ADMIN_REVIEW_SHIFT_END_GRACE_MS;
                const staleByAge = ageMs >= MAX_OVERNIGHT_CARRYOVER_HOURS * MS_PER_HOUR;
                if (!pastGrace && !staleByAge) return;
                const severity = staleByAge || pastScheduledEndMs >= 6 * MS_PER_HOUR ? 'critical' : 'warning';
                const scheduleNote = pastGrace ? ` · scheduled shift ended ${adminOpsFormatAge(Math.max(0, pastScheduledEndMs))} ago` : '';
                issues.push(adminReviewIssue('Attendance', severity, `${name} · Missing Time Out`, `${date} · Time In ${formatManilaTime(rec.timeIn)} · open ${adminOpsFormatAge(ageMs)}${scheduleNote} · ${podContextLabel(pod)}`, 'agent-attendance', { name, date, pod }));
            });
            return issues;
        }

        function adminReviewLongBreakIssues(nowMs) {
            const issues = [];
            Object.entries(allRecords || {}).forEach(([key, rec]) => {
                if (!rec || !rec.timeIn || !rec.startBreak || rec.endBreak || rec.logOut || isVoidedAttendanceRecord(rec)) return;
                const splitAt = key.indexOf('|');
                if (splitAt < 0) return;
                const date = key.slice(0, splitAt);
                const name = key.slice(splitAt + 1);
                const pod = rec.pod || podOf(name) || '';
                if (!adminOpsPodInScope(pod)) return;
                const breakStartMs = new Date(rec.startBreak).getTime();
                if (!Number.isFinite(breakStartMs)) return;
                const allowanceMs = Math.max(1, Number(getBreakPolicyMinutes(rec) || BREAK_ALLOWANCE_MINUTES)) * 60000;
                const elapsedMs = Math.max(0, nowMs - breakStartMs);
                if (elapsedMs < allowanceMs + ADMIN_REVIEW_BREAK_GRACE_MS) return;
                const excessMs = elapsedMs - allowanceMs;
                const severity = excessMs >= 60 * 60000 ? 'critical' : 'warning';
                issues.push(adminReviewIssue('Attendance', severity, `${name} · Break over allowance`, `${date} · break open ${adminOpsFormatAge(elapsedMs)} · ${adminOpsFormatAge(excessMs)} over the ${Math.round(allowanceMs / 60000)} min allowance · ${podContextLabel(pod)}`, 'agent-attendance', { name, date, pod }));
            });
            return issues;
        }

        function adminReviewAttendanceIntegrityIssues() {
            const issues = [];
            Object.entries(allRecords || {}).forEach(([key, rec]) => {
                if (!rec || isVoidedAttendanceRecord(rec)) return;
                const splitAt = key.indexOf('|');
                if (splitAt < 0) return;
                const date = key.slice(0, splitAt);
                const name = key.slice(splitAt + 1);
                const pod = rec.pod || podOf(name) || '';
                if (!adminOpsPodInScope(pod)) return;
                const labels = [];
                let critical = false;
                const values = {};
                ['timeIn','startBreak','endBreak','logOut'].forEach(field => {
                    if (!rec[field]) return;
                    const value = new Date(rec[field]).getTime();
                    values[field] = value;
                    if (!Number.isFinite(value)) { labels.push(`${field} is invalid`); critical = true; }
                });
                if (rec.startBreak && !rec.timeIn) { labels.push('Start Break without Time In'); critical = true; }
                if (rec.endBreak && !rec.startBreak) { labels.push('End Break without Start Break'); critical = true; }
                if (rec.logOut && !rec.timeIn) { labels.push('Time Out without Time In'); critical = true; }
                if (Number.isFinite(values.timeIn) && Number.isFinite(values.startBreak) && values.startBreak <= values.timeIn) { labels.push('Start Break is not after Time In'); critical = true; }
                if (Number.isFinite(values.startBreak) && Number.isFinite(values.endBreak) && values.endBreak <= values.startBreak) { labels.push('End Break is not after Start Break'); critical = true; }
                if (Number.isFinite(values.timeIn) && Number.isFinite(values.logOut) && values.logOut <= values.timeIn) { labels.push('Time Out is not after Time In'); critical = true; }
                if (Number.isFinite(values.endBreak) && Number.isFinite(values.logOut) && values.logOut <= values.endBreak) { labels.push('Time Out is not after End Break'); critical = true; }
                if (rec.startBreak && !rec.endBreak && rec.logOut) { labels.push('Time Out recorded while break is still open'); critical = true; }
                const seen = new Map();
                ['timeIn','startBreak','endBreak','logOut'].forEach(field => {
                    const raw = rec[field];
                    if (!raw) return;
                    if (seen.has(raw)) labels.push(`${field} duplicates ${seen.get(raw)}`);
                    else seen.set(raw, field);
                });
                if (!labels.length) return;
                const unique = Array.from(new Set(labels));
                issues.push(adminReviewIssue('Attendance', critical ? 'critical' : 'warning', `${name} · Attendance correction required`, `${date} · ${unique.slice(0, 3).join(' · ')}${unique.length > 3 ? ` · +${unique.length - 3} more` : ''} · ${podContextLabel(pod)}`, 'agent-attendance', { name, date, pod }));
            });
            return issues;
        }

        function adminReviewIncompleteTlIssues(nowMs) {
            const issues = [];
            Object.entries(allTeamLeaderRecords || {}).forEach(([key, rec]) => {
                if (!rec || !rec.timeIn || rec.logOut) return;
                const splitAt = key.indexOf('|');
                if (splitAt < 0) return;
                const date = key.slice(0, splitAt);
                const name = key.slice(splitAt + 1);
                const pod = TEAM_LEADER_POD_BY_NAME[name] || rec.pod || '';
                if (!adminOpsPodInScope(pod)) return;
                const startMs = new Date(rec.timeIn).getTime();
                if (!Number.isFinite(startMs)) return;
                const ageHours = Math.max(0, (nowMs - startMs) / MS_PER_HOUR);
                if (ageHours <= MAX_OVERNIGHT_CARRYOVER_HOURS) return;
                const severity = ageHours >= 36 ? 'critical' : 'warning';
                issues.push(adminReviewIssue('TL Attendance', severity, `${name} · Incomplete TL Shift`, `${date} · Time In ${formatManilaTime(rec.timeIn)} · open ${adminOpsFormatAge(nowMs - startMs)} · ${podContextLabel(pod)}`, 'tl-attendance', { name, date, pod, dedupeKey:`tl-attendance-availability:${name}|${date}|${pod}` }));
            });
            return issues;
        }

        function adminReviewLeaveIssues() {
            return pendingLeaveApprovalRequests().filter(request => canReviewLeaveRequest(request) && adminOpsPodInScope(request.pod || '')).map(request => adminReviewIssue(
                'Leave', 'warning', `${agentDisplayName(request.agentName) || 'Agent'} · ${request.leaveType || 'Leave'} approval`, `${formatLeaveRange(request)} · ${request.pod ? podContextLabel(request.pod) : 'Unassigned POD'}${leaveRequestHasAttendanceConflict(request) ? ' · attendance conflict detected' : ''}`, 'leave', { requestId:request.id, name:request.agentName || '', pod:request.pod || '' }
            ));
        }

        function adminReviewAgentSecurityIssues(nowMs) {
            const issues = [];
            currentTeamEmployees().filter(emp => adminOpsPodInScope(emp.pod)).forEach(emp => {
                const state = getAgentSecurityState(emp.name);
                if (state.invalid || state.locked || state.legacySharedCredential || state.needsSetup) {
                    let title = `${agentDisplayName(emp.name)} · Account needs attention`;
                    let detail = podContextLabel(emp.pod);
                    let severity = 'warning';
                    if (state.invalid) { title = `${agentDisplayName(emp.name)} · Invalid credential record`; detail += ' · reset required'; severity = 'critical'; }
                    else if (state.locked) { title = `${agentDisplayName(emp.name)} · Account locked`; detail += state.record && state.record.lockedUntil ? ` · until ${formatAgentSecurityLastLogin(new Date(state.record.lockedUntil).toISOString())}` : ''; severity = 'critical'; }
                    else if (state.legacySharedCredential) { title = `${agentDisplayName(emp.name)} · Legacy password reset required`; detail += ' · generate a unique temporary password'; }
                    else if (state.needsSetup) { title = `${agentDisplayName(emp.name)} · Account not set up`; detail += ' · generate a temporary password'; }
                    issues.push(adminReviewIssue('Security', severity, title, detail, 'agent-security', { name:emp.name, pod:emp.pod }));
                    return;
                }
                const issuedMs = state.temporaryPassword && state.record && state.record.temporaryIssuedAt ? new Date(state.record.temporaryIssuedAt).getTime() : NaN;
                if (Number.isFinite(issuedMs) && nowMs - issuedMs >= ADMIN_REVIEW_TEMP_CREDENTIAL_AGE_MS) {
                    issues.push(adminReviewIssue('Security', 'info', `${agentDisplayName(emp.name)} · Temporary password still active`, `${podContextLabel(emp.pod)} · issued ${adminOpsFormatAge(nowMs - issuedMs)} ago · password change still required`, 'agent-security', { name:emp.name, pod:emp.pod }));
                }
            });
            return issues;
        }

        function adminReviewTlSecurityIssues(nowMs) {
            const issues = [];
            teamLeadersForAttendanceTeam(activeTeam).filter(tl => adminOpsPodInScope(tl.pod)).forEach(tl => {
                const record = readTeamLeaderAuthRecordLocal(tl.name);
                if (!record) {
                    issues.push(adminReviewIssue('TL Security', 'warning', `${agentDisplayName(tl.name)} · TL account not set up`, `${podContextLabel(tl.pod)} · generate a unique temporary password`, 'tl-security', { name:tl.name, pod:tl.pod }));
                    return;
                }
                const legacy = !!(record && !record.invalid && record.isDefault && !record.temporaryIssuedAt);
                const locked = !!(record && (record.invalid || Number(record.lockedUntil) > nowMs));
                if (locked || legacy) {
                    issues.push(adminReviewIssue('TL Security', locked ? 'critical' : 'warning', `${agentDisplayName(tl.name)} · ${record.invalid ? 'Invalid TL credential' : locked ? 'TL account locked' : 'Legacy TL password reset required'}`, `${podContextLabel(tl.pod)}${record.lockedUntil && Number(record.lockedUntil) > nowMs ? ` · locked for ${adminOpsFormatAge(Number(record.lockedUntil) - nowMs)}` : ''}`, 'tl-security', { name:tl.name, pod:tl.pod }));
                    return;
                }
                const issuedMs = record.isDefault && record.temporaryIssuedAt ? new Date(record.temporaryIssuedAt).getTime() : NaN;
                if (Number.isFinite(issuedMs) && nowMs - issuedMs >= ADMIN_REVIEW_TEMP_CREDENTIAL_AGE_MS) {
                    issues.push(adminReviewIssue('TL Security', 'info', `${agentDisplayName(tl.name)} · TL temporary password still active`, `${podContextLabel(tl.pod)} · issued ${adminOpsFormatAge(nowMs - issuedMs)} ago`, 'tl-security', { name:tl.name, pod:tl.pod }));
                }
            });
            return issues;
        }

        function adminReviewNetworkIssues(nowMs) {
            const scoped = Object.values(allSpeedTests || {}).filter(item => item && adminOpsPodInScope(item.pod || podOf(item.name) || ''));
            return latestNetworkAttemptByAgent(scoped).filter(item => {
                const tsMs = new Date(item.ts || '').getTime();
                return Number.isFinite(tsMs) && nowMs - tsMs <= ADMIN_REVIEW_NETWORK_WINDOW_MS && isNetworkProblem(item);
            }).map(item => {
                const quality = getNetworkQuality(item);
                const tsMs = new Date(item.ts).getTime();
                const status = speedTestStatus(item);
                const detail = `${item.pod ? podContextLabel(item.pod) : 'Unassigned POD'} · ${status === 'failed' ? 'test failed' : quality.label}${Number.isFinite(tsMs) ? ` · ${adminOpsFormatAge(nowMs - tsMs)} ago` : ''}`;
                return adminReviewIssue('Network', quality.key === 'poor' || quality.key === 'failed' ? 'warning' : 'info', `${agentDisplayName(item.name) || 'Agent'} · Network ${status === 'failed' ? 'test failed' : quality.label.toLowerCase()}`, detail, 'network', { name:item.name || '', pod:item.pod || '' });
            });
        }

        function adminReviewCoachingIssues() {
            try {
                const api = window.TrinoTimeCoaching;
                if (!api || typeof api.getReviewSnapshot !== 'function') return [];
                const snapshot = api.getReviewSnapshot();
                return (snapshot.items || []).map(item => adminReviewIssue('Coaching', item.severity || 'warning', item.title || 'Coaching session needs review', item.detail || '', 'coaching', { name:item.name || '', sessionId:item.sessionId || '' }));
            } catch (_) { return []; }
        }

        function adminReviewSyncIssue(health) {
            if (!health || health.state === 'healthy') return [];
            const severity = health.state === 'critical' || health.state === 'offline' ? 'critical' : 'warning';
            return [adminReviewIssue('System', severity, health.label, health.summary, 'retry-sync')];
        }

        function getAdminReviewSnapshot(nowMs = getTrueNowMs()) {
            const health = adminSystemHealthSnapshot(nowMs);
            const grouped = {
                attendance: [...adminReviewIncompleteAgentIssues(nowMs), ...adminReviewLongBreakIssues(nowMs), ...adminReviewAttendanceIntegrityIssues(), ...adminReviewIncompleteTlIssues(nowMs)],
                leave: adminReviewLeaveIssues(),
                security: [...adminReviewAgentSecurityIssues(nowMs), ...adminReviewTlSecurityIssues(nowMs)],
                network: adminReviewNetworkIssues(nowMs),
                coaching: adminReviewCoachingIssues(),
                sync: adminReviewSyncIssue(health)
            };
            Object.keys(grouped).forEach(key => { grouped[key] = adminReviewDeduplicateIssues(grouped[key]); });
            const issues = adminReviewDeduplicateIssues(Object.values(grouped).flat());
            const rank = { critical:0, warning:1, info:2 };
            issues.sort((a,b) => (rank[a.severity] ?? 9) - (rank[b.severity] ?? 9) || String(a.category).localeCompare(String(b.category)) || String(a.title).localeCompare(String(b.title)));
            const critical = issues.filter(item => item.severity === 'critical').length;
            const signature = JSON.stringify({
                team:activeTeam, pod:activePod, critical,
                counts:Object.fromEntries(Object.entries(grouped).map(([key,value]) => [key,value.length])),
                health:health.state, pending:health.pending.total,
                ids:issues.map(item => [item.category,item.severity,item.title,item.date || '',item.requestId || '',item.sessionId || ''])
            });
            return { health, grouped, issues, critical, signature };
        }

        function adminReviewActionLabel(action) {
            return ({
                'agent-attendance':'Review record', 'tl-attendance':'Review TL shift', 'leave':'Review leave',
                'agent-security':'Open security', 'tl-security':'Open TL security', 'network':'View network',
                'coaching':'Open coaching', 'retry-sync':'Retry sync'
            })[action] || 'Review';
        }

        function renderSystemHealth(snapshot) {
            const card = $('systemHealthCard');
            const badge = $('systemHealthStatus');
            const overview = $('systemHealthOverview');
            const grid = $('systemHealthGrid');
            if (!card || !snapshot) return;
            card.dataset.health = snapshot.state;
            if (badge) { badge.dataset.state = snapshot.state; badge.textContent = snapshot.label; }
            if (overview) overview.textContent = snapshot.summary;
            if (grid) {
                grid.innerHTML = snapshot.metrics.map(metric => `<div class="system-health-metric" data-state="${escapeHtml(metric.state || 'neutral')}"><span>${escapeHtml(metric.label)}</span><strong>${escapeHtml(metric.value)}</strong></div>`).join('');
            }
            const retry = $('systemHealthRetryBtn');
            if (retry) {
                retry.disabled = reconnectPromise !== null;
                retry.textContent = reconnectPromise ? 'Checking…' : (snapshot.pending.total ? 'Retry Sync' : 'Check Live Server');
            }
        }

        function clearAdminOpsSensitiveDom() {
            const badge = $('adminReviewBadge');
            if (badge) { badge.dataset.state = 'clear'; badge.textContent = 'Admin only'; }
            ['adminReviewAttendanceCount','adminReviewLeaveCount','adminReviewSecurityCount','adminReviewNetworkCount','adminReviewCoachingCount','adminReviewSyncCount'].forEach(id => {
                const el = $(id);
                if (el) el.textContent = '0';
            });
            const list = $('adminReviewList');
            if (list) list.innerHTML = '<div class="admin-review-empty">Admin access is required to view operational review data.</div>';
            const card = $('systemHealthCard');
            if (card) card.dataset.health = 'checking';
            const status = $('systemHealthStatus');
            if (status) { status.dataset.state = 'checking'; status.textContent = 'Admin only'; }
            const overview = $('systemHealthOverview');
            if (overview) overview.textContent = 'System Health details are available to authenticated Admins.';
            const grid = $('systemHealthGrid');
            if (grid) grid.innerHTML = '';
        }

        function refreshAdminRecoveryVaultFromOps() {
            // v76 Recovery Vault is loaded after this fragment. Keep this lookup
            // guarded so v75/v76 startup order stays safe while role/session changes
            // still scrub and refresh recovery data through the Admin Ops lifecycle.
            const recovery = window.TrinoTimeCore && window.TrinoTimeCore.recovery;
            if (recovery && typeof recovery.refresh === 'function') recovery.refresh();
        }

        function renderAdminOpsCenter(options = {}) {
            const center = $('adminOpsCenter');
            if (!center) return;
            const visible = adminOpsIsVisible();
            center.hidden = !visible;
            center.classList.toggle('is-visible', visible);
            if (!visible) {
                adminOpsLastSignature = '';
                clearAdminOpsSensitiveDom();
                refreshAdminRecoveryVaultFromOps();
                return;
            }
            // Recovery has a separate short-lived data store. Refresh it even when
            // the Review Center snapshot itself has not changed.
            refreshAdminRecoveryVaultFromOps();
            const snapshot = options.snapshot || getAdminReviewSnapshot();
            if (!options.force && snapshot.signature === adminOpsLastSignature) return;
            const badge = $('adminReviewBadge');
            if (badge) {
                badge.dataset.state = snapshot.critical ? 'critical' : (snapshot.issues.length ? 'attention' : 'clear');
                badge.textContent = snapshot.issues.length ? `${snapshot.issues.length} item${snapshot.issues.length === 1 ? '' : 's'} ${snapshot.issues.length === 1 ? 'needs' : 'need'} review` : 'All clear';
            }
            const counts = {
                adminReviewAttendanceCount:snapshot.grouped.attendance.length,
                adminReviewLeaveCount:snapshot.grouped.leave.length,
                adminReviewSecurityCount:snapshot.grouped.security.length,
                adminReviewNetworkCount:snapshot.grouped.network.length,
                adminReviewCoachingCount:snapshot.grouped.coaching.length,
                adminReviewSyncCount:snapshot.grouped.sync.length
            };
            Object.entries(counts).forEach(([id,value]) => { const el=$(id); if(el) el.textContent=String(value); });
            const list = $('adminReviewList');
            if (list) {
                const shown = snapshot.issues.slice(0, ADMIN_REVIEW_RENDER_LIMIT);
                list.innerHTML = shown.length ? shown.map((item,index) => {
                    const payload = encodeURIComponent(JSON.stringify({ action:item.action, name:item.name || '', date:item.date || '', requestId:item.requestId || '', sessionId:item.sessionId || '' }));
                    return `<div class="admin-review-item" data-severity="${escapeHtml(item.severity)}"><span class="admin-review-severity" aria-hidden="true"></span><div class="admin-review-copy"><span class="admin-review-category">${escapeHtml(item.category)}</span><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.detail)}</span></div>${item.action ? `<button class="admin-review-action" type="button" data-admin-review-payload="${payload}" aria-label="${escapeHtml(adminReviewActionLabel(item.action))}: ${escapeHtml(item.title)}">${escapeHtml(adminReviewActionLabel(item.action))}</button>` : ''}</div>`;
                }).join('') : '<div class="admin-review-empty"><strong>No Admin action is currently required.</strong><br>Attendance, leave, security, network, coaching, and sync checks are clear for this view.</div>';
                if (snapshot.issues.length > shown.length) list.innerHTML += `<div class="admin-review-more">Showing the highest-priority ${shown.length} of ${snapshot.issues.length} review items.</div>`;
            }
            renderSystemHealth(snapshot.health);
            adminOpsLastSignature = snapshot.signature;
            adminOpsLastRenderAt = Date.now();
        }

        function updateAdminOpsCenterLive(nowMs = getTrueNowMs()) {
            if (!adminOpsIsVisible()) return;
            if (Date.now() - adminOpsLastRenderAt < 10000) return;
            const snapshot = getAdminReviewSnapshot(nowMs);
            if (snapshot.signature !== adminOpsLastSignature) renderAdminOpsCenter({ snapshot });
            else renderSystemHealth(snapshot.health);
            adminOpsLastRenderAt = Date.now();
        }

        function openAdminOpsSyncDiagnostics() {
            if (!TrinoPermissions.can('system.health.view')) return;
            const gear = $('settingsGearBtn');
            if (gear) gear.click();
            setTimeout(() => {
                const syncTab = $('settingsSyncTabBtn');
                if (syncTab) syncTab.click();
            }, 0);
        }

        function focusAdminSecurityTarget(name, isTl = false) {
            const panel = $('agentSecurityPanel');
            if (!panel) return;
            setAgentSecurityCollapsed(false);
            if (isTl) {
                const select = $('teamLeaderSecuritySelect');
                if (select && Array.from(select.options).some(option => option.value === name)) select.value = name;
            } else {
                agentSecuritySearchQuery = name || '';
                const input = $('agentSecuritySearch');
                if (input) input.value = agentSecuritySearchQuery;
            }
            scheduleAgentSecurityPanelRender();
            setTimeout(() => scrollAndFocusSection(panel), 0);
        }

        function handleAdminReviewAction(payload) {
            if (!adminOpsIsVisible() || !payload || !payload.action) return;
            const action = payload.action;
            if (action === 'agent-attendance') { openEditModal(payload.date, payload.name); return; }
            if (action === 'tl-attendance') { openTlAttendanceAdminEdit(payload.date, payload.name); return; }
            if (action === 'leave') {
                try { leaveV2ListFilter = 'pending'; } catch (_) {}
                openLeaveRequestModal();
                return;
            }
            if (action === 'agent-security') { focusAdminSecurityTarget(payload.name, false); return; }
            if (action === 'tl-security') { focusAdminSecurityTarget(payload.name, true); return; }
            if (action === 'network') { openNetworkAgentSummary(payload.name); return; }
            if (action === 'coaching') {
                try {
                    const employeeFilter = $('coachingReportEmp');
                    if (employeeFilter && payload.name && Array.from(employeeFilter.options || []).some(option => option.value === payload.name)) employeeFilter.value = payload.name;
                    if (window.TrinoTimeCoaching && typeof window.TrinoTimeCoaching.openReport === 'function') window.TrinoTimeCoaching.openReport();
                } catch (_) {}
                return;
            }
            if (action === 'retry-sync') {
                void runAsyncAction(() => reconnectToLiveServer({ userInitiated:true }), 'Retry live sync');
            }
        }

        const adminOpsCenter = $('adminOpsCenter');
        if (adminOpsCenter) {
            adminOpsCenter.addEventListener('click', event => {
                const actionButton = event.target.closest('[data-admin-review-payload]');
                if (!actionButton) return;
                try { handleAdminReviewAction(JSON.parse(decodeURIComponent(actionButton.dataset.adminReviewPayload || ''))); }
                catch (_) { showToast('Could not open this review item. Refresh the Admin Review Center and try again.'); }
            });
        }
        const adminOpsRefreshBtn = $('adminOpsRefreshBtn');
        if (adminOpsRefreshBtn) adminOpsRefreshBtn.addEventListener('click', () => renderAdminOpsCenter({ force:true }));
        const adminOpsDiagnosticsBtn = $('adminOpsDiagnosticsBtn');
        if (adminOpsDiagnosticsBtn) adminOpsDiagnosticsBtn.addEventListener('click', openAdminOpsSyncDiagnostics);
        const systemHealthDiagnosticsBtn = $('systemHealthDiagnosticsBtn');
        if (systemHealthDiagnosticsBtn) systemHealthDiagnosticsBtn.addEventListener('click', openAdminOpsSyncDiagnostics);
        const systemHealthRetryBtn = $('systemHealthRetryBtn');
        if (systemHealthRetryBtn) systemHealthRetryBtn.addEventListener('click', () => {
            if (!TrinoPermissions.can('system.health.retry')) return;
            void runAsyncAction(async () => {
                await reconnectToLiveServer({ userInitiated:true });
                renderAdminOpsCenter({ force:true });
            }, 'Check live system health');
        });
        window.addEventListener('online', () => setTimeout(() => renderAdminOpsCenter({ force:true }), 0));
        window.addEventListener('offline', () => setTimeout(() => renderAdminOpsCenter({ force:true }), 0));

        window.TrinoTimeCore = window.TrinoTimeCore || {};
        window.TrinoTimeCore.adminOps = Object.freeze({
            getReviewSnapshot: () => adminOpsIsVisible() ? getAdminReviewSnapshot() : null,
            getSystemHealth: () => TrinoPermissions.can('system.health.view') ? adminSystemHealthSnapshot() : null,
            refresh: () => renderAdminOpsCenter({ force:true }),
            updateLive: nowMs => updateAdminOpsCenterLive(nowMs),
            version: '1.0.6'
        });

        // Fragment 23 is intentionally the last core fragment. Render once only
        // after its state has initialized so earlier startup calls cannot cross
        // the temporal-dead-zone of this module's let/const bindings.
        renderAdminOpsCenter({ force:true });


