        async function revokeTlWorkAuthorization(id){const item=allShiftOverrides[id];if(!item||item.overrideKind!==TL_MEDIUM_AUTH_KIND)return;TrinoPermissions.require('schedule.tl_work_authorization.manage',{name:item.name,pod:item.pod},'An authenticated Admin session is required to revoke this authorization.');if(dayOffSwapIsPast(item.date))return showToast('Completed Work on Day Off authorizations are retained as history.');if(hasAttendanceActivity(item.name,item.date))return showToast('This authorization cannot be revoked after attendance activity has started for that date.');if(!(await showConfirmAsync('Revoke Work Authorization?',`Revoke permission for <strong>${escapeHtml(agentDisplayName(item.name))}</strong> to work on the scheduled day off <strong>${escapeHtml(formatDayOffSwapDate(item.date))}</strong>?`,{confirmLabel:'Revoke Authorization',cancelLabel:'Keep Authorization',tone:'danger',kind:'tl-work-authorization-revoke'})))return;const actor=tlMediumActor();await deleteShiftOverride(id);await logAudit('tl_work_on_dayoff_revoked',{targetTeamLeader:item.name,targetRole:'Team Leader',name:item.name,pod:item.pod,date:item.date,authorizationId:item.id,reason:item.reason||'',schedule_action:'dayoff_work_revoke',modified_by:actor.id,old:item,new:null});tlMediumRefreshSurfaces(item.pod);showToast('Work on Day Off authorization revoked.');}
        const tlMediumLegacyIncompleteTlIssues=adminReviewIncompleteTlIssues;
        adminReviewIncompleteTlIssues=function(nowMs){const issues=tlMediumLegacyIncompleteTlIssues(nowMs);Object.entries(allTeamLeaderRecords||{}).forEach(([key,rec])=>{if(!rec||!rec.timeIn||rec.logOut)return;const split=key.indexOf('|');if(split<0)return;const date=key.slice(0,split),name=key.slice(split+1),pod=(TEAM_LEADER_POD_BY_NAME&&TEAM_LEADER_POD_BY_NAME[name])||rec.pod||'';if(!adminOpsPodInScope(pod))return;const av=resolveEffectiveAvailability(name,date,pod,{role:'teamleader',atMs:new Date(rec.timeIn).getTime()});if(!av.conflict)return;const dedupeKey=`tl-attendance-availability:${name}|${date}|${pod}`;issues.push(adminReviewIssue('TL Availability','warning',`${name} · ${av.baseSourceKind==='day_off'?'Day Off / Attendance Conflict':'Leave / Attendance Conflict'}`,`${date} · ${av.reason} · attendance started ${formatManilaTime(rec.timeIn)} · ${podContextLabel(pod)}`,'tl-attendance',{name,date,pod,dedupeKey}));});return adminReviewDeduplicateIssues(issues);};
        const tlMediumLegacyTlHomeStatusState=tlHomeStatusState;
        tlHomeStatusState=function(rec,incompletePrevious,availability){if((!rec||!rec.timeIn)&&availability&&availability.code==='admin_work_override'&&availability.workAuthorization)return {state:'idle',label:'Authorized Work'};return tlMediumLegacyTlHomeStatusState(rec,incompletePrevious,availability);};
        $('exceptionCreateTlDayBtn')&&$('exceptionCreateTlDayBtn').addEventListener('click',openTlDateOverrideModal);
        $('exceptionAuthorizeTlWorkBtn')&&$('exceptionAuthorizeTlWorkBtn').addEventListener('click',openTlWorkAuthorizationModal);
        $('tlDayOverrideCancelBtn')&&$('tlDayOverrideCancelBtn').addEventListener('click',()=>$('tlDayOverrideOverlay').classList.remove('open'));
        $('tlDayOverrideSaveBtn')&&$('tlDayOverrideSaveBtn').addEventListener('click',()=>void runAsyncAction(saveTlDateOverrideFromModal,'Save Team Leader date override'));
        $('tlDayOverrideDate')&&$('tlDayOverrideDate').addEventListener('change',tlMediumRefreshDateOverrideState);
        $('tlDayOverrideName')&&$('tlDayOverrideName').addEventListener('change',tlMediumRefreshDateOverrideState);
        $('tlDayOverrideMode')&&$('tlDayOverrideMode').addEventListener('change',tlMediumRefreshDateOverrideState);
        $('tlDayOverrideOverlay')&&$('tlDayOverrideOverlay').addEventListener('click',e=>{if(e.target.id==='tlDayOverrideOverlay')$('tlDayOverrideOverlay').classList.remove('open');});
        $('tlWorkAuthorizationCancelBtn')&&$('tlWorkAuthorizationCancelBtn').addEventListener('click',()=>$('tlWorkAuthorizationOverlay').classList.remove('open'));
        $('tlWorkAuthorizationSaveBtn')&&$('tlWorkAuthorizationSaveBtn').addEventListener('click',()=>void runAsyncAction(saveTlWorkAuthorizationFromModal,'Authorize Team Leader work on day off'));
        $('tlWorkAuthorizationDate')&&$('tlWorkAuthorizationDate').addEventListener('change',tlMediumRefreshWorkAuthState);
